css:
[data-workspace-area="conversation"] { background: var(--theme-background-image) center / cover no-repeat !important; }
:root:not(.dark) [data-workspace-area="conversation"] {
  position: relative;
  isolation: isolate;
  background: #e5e5e5 !important;
}
:root:not(.dark) [data-workspace-area="conversation"]::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: var(--theme-background-image, none) center / cover no-repeat;
  filter: grayscale(1) invert(1);
  opacity: .72;
}

/* Some controls use the stock color scale directly. */
:root:not(.dark) {
  --color-red-50: #fafafa !important;
  --color-pink-50: #fafafa !important;
